import Vue from 'vue'; // Import Vue correctly
import App from './App.vue'; // Your main app component
import { Loader } from '@googlemaps/js-api-loader'; // Google Maps loader

// Set up Google Maps
const loader = new Loader({
  apiKey: 'AIzaSyCOrCd4askrLzy3Ml2LGzsX1a1pHmuLC6k', // Replace with your Google Maps API key
  version: 'weekly',
  libraries: ['places'], // For address autocomplete later
});

// Load Google Maps, then start Vue
loader.load().then(() => {
  console.log('Google Maps is ready!');

  // Create the Vue app
